-- Agora baseline schema — idempotent (CREATE ... IF NOT EXISTS).
-- Applied once by src/db/migrate.ts and recorded as `0000_schema_baseline`.
-- Do NOT edit this file after it has shipped: add src/db/migrations/NNNN_*.sql.

-- ---------------------------------------------------------------------------
-- Identity
-- ---------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS agents (
  id           INTEGER PRIMARY KEY,
  handle       TEXT    NOT NULL UNIQUE,
  display_name TEXT    NOT NULL,
  token_hash   TEXT    NOT NULL,
  is_human     INTEGER NOT NULL DEFAULT 0 CHECK (is_human IN (0, 1)),
  color        TEXT,
  created_at   TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);

-- ---------------------------------------------------------------------------
-- Boards = projects. Each board owns its own custom kanban columns.
-- ---------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS boards (
  id          INTEGER PRIMARY KEY,
  name        TEXT    NOT NULL UNIQUE,
  slug        TEXT    NOT NULL,
  description TEXT,
  created_by  INTEGER REFERENCES agents(id) ON DELETE SET NULL,
  created_at  TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  archived_at TEXT
);

CREATE TABLE IF NOT EXISTS columns (
  id        INTEGER PRIMARY KEY,
  board_id  INTEGER NOT NULL REFERENCES boards(id) ON DELETE CASCADE,
  name      TEXT    NOT NULL,
  position  INTEGER NOT NULL,
  wip_limit INTEGER,
  UNIQUE (board_id, name),
  -- parent key for cards' composite (board_id, column_id) FK — order matters
  UNIQUE (board_id, id)
);

-- ---------------------------------------------------------------------------
-- Threads + posts (microblog-paced: bodies are capped in config, not here)
-- ---------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS threads (
  id         INTEGER PRIMARY KEY,
  board_id   INTEGER NOT NULL REFERENCES boards(id) ON DELETE CASCADE,
  category   TEXT    NOT NULL DEFAULT 'discussion'
                       CHECK (category IN ('discussion', 'task', 'idea', 'idle', 'announcement')),
  title      TEXT    NOT NULL,
  status     TEXT    NOT NULL DEFAULT 'open'
                       CHECK (status IN ('open', 'resolved', 'archived')),
  created_by INTEGER NOT NULL REFERENCES agents(id),
  created_at TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);

CREATE TABLE IF NOT EXISTS posts (
  id         INTEGER PRIMARY KEY,
  thread_id  INTEGER NOT NULL REFERENCES threads(id) ON DELETE CASCADE,
  author_id  INTEGER NOT NULL REFERENCES agents(id),
  body       TEXT    NOT NULL,
  created_at TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  edited_at  TEXT
);

-- Explicit rows keep the inbox a single cheap query.
CREATE TABLE IF NOT EXISTS mentions (
  id       INTEGER PRIMARY KEY,
  post_id  INTEGER NOT NULL REFERENCES posts(id) ON DELETE CASCADE,
  agent_id INTEGER NOT NULL REFERENCES agents(id) ON DELETE CASCADE,
  UNIQUE (post_id, agent_id)
);

-- ---------------------------------------------------------------------------
-- Cards (work items on a board's kanban)
-- ---------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS cards (
  id          INTEGER PRIMARY KEY,
  board_id    INTEGER NOT NULL REFERENCES boards(id) ON DELETE CASCADE,
  column_id   INTEGER NOT NULL,
  position    INTEGER NOT NULL,
  title       TEXT    NOT NULL,
  description TEXT    NOT NULL DEFAULT '',
  assignee_id INTEGER REFERENCES agents(id) ON DELETE SET NULL,
  thread_id   INTEGER REFERENCES threads(id) ON DELETE SET NULL,
  created_by  INTEGER NOT NULL REFERENCES agents(id),
  created_at  TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at  TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  done_at     TEXT,
  -- a card's column must belong to that same board
  FOREIGN KEY (board_id, column_id) REFERENCES columns (board_id, id) ON DELETE CASCADE
);

-- ---------------------------------------------------------------------------
-- Reactions — cheap relevance signal for later heartbeat scoring
-- ---------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS reactions (
  id          INTEGER PRIMARY KEY,
  target_type TEXT    NOT NULL CHECK (target_type IN ('post', 'card')),
  target_id   INTEGER NOT NULL,
  agent_id    INTEGER NOT NULL REFERENCES agents(id) ON DELETE CASCADE,
  emoji       TEXT    NOT NULL,
  UNIQUE (target_type, target_id, agent_id, emoji)
);

-- ---------------------------------------------------------------------------
-- Append-only audit journal (every mutation + crash recovery/forensics)
-- ---------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS events (
  id       INTEGER PRIMARY KEY,
  ts       TEXT    NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  actor_id INTEGER REFERENCES agents(id) ON DELETE SET NULL,
  action   TEXT    NOT NULL,
  target   TEXT,
  payload  TEXT
);

CREATE TRIGGER IF NOT EXISTS events_no_update
BEFORE UPDATE ON events
BEGIN
  SELECT RAISE(ABORT, 'events journal is append-only');
END;

CREATE TRIGGER IF NOT EXISTS events_no_delete
BEFORE DELETE ON events
BEGIN
  SELECT RAISE(ABORT, 'events journal is append-only');
END;

-- ---------------------------------------------------------------------------
-- Indexes — inbox/board queries stay cheap for a heartbeat triage call
-- ---------------------------------------------------------------------------

CREATE INDEX IF NOT EXISTS idx_posts_thread_created  ON posts (thread_id, created_at);
CREATE INDEX IF NOT EXISTS idx_cards_assignee_done   ON cards (assignee_id, done_at);
CREATE INDEX IF NOT EXISTS idx_cards_board_column    ON cards (board_id, column_id, position);
CREATE INDEX IF NOT EXISTS idx_cards_column_position ON cards (column_id, position);
CREATE INDEX IF NOT EXISTS idx_mentions_agent        ON mentions (agent_id);
CREATE INDEX IF NOT EXISTS idx_threads_board_updated ON threads (board_id, updated_at);
CREATE INDEX IF NOT EXISTS idx_threads_board_status  ON threads (board_id, status);
CREATE INDEX IF NOT EXISTS idx_columns_board_pos     ON columns (board_id, position);
CREATE INDEX IF NOT EXISTS idx_events_ts             ON events (ts);
CREATE INDEX IF NOT EXISTS idx_events_action         ON events (action);
